/**
 * Writes src/theme/tokens.generated.ts from the Style Dictionary React Native output of @xos/tokens
 * (dist/native/base.js and theme.{dark,light,sunlight}.js). Values are normalized for React Native:
 * dimensions become numbers of points, durations become milliseconds, springs become
 * { damping, stiffness, mass }, and typography gets an absolute line height and a string weight.
 *
 * Usage: node scripts/generate-theme.mjs [--check]
 * With --check, writes nothing and exits 1 when the generated file is out of date.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as prettier from "prettier";

const here = dirname(fileURLToPath(import.meta.url));
const target = join(here, "../src/theme/tokens.generated.ts");
const THEMES = ["dark", "light", "sunlight"];

/** Base token groups that apply on device, keyed by the Style Dictionary name prefix. */
const BASE_GROUPS = [
  ["space", "space"],
  ["radius", "radius"],
  ["strokeWidth", "strokeWidth"],
  ["opacity", "opacity"],
  ["iconSize", "iconSize"],
  ["density", "density"],
  ["motionDuration", "duration"],
  ["motionEasing", "easing"],
  ["motionSpring", "spring"],
  ["fontWeight", "fontWeight"],
  ["typography", "typography"],
];
const THEME_GROUPS = [
  ["color", "color"],
  ["shadow", "shadow"],
];

function lowerFirst(s) {
  return s.charAt(0).toLowerCase() + s.slice(1);
}

function normalize(value) {
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    if (typeof value.number === "number") return value.number;
    if (typeof value.fontSize === "string") {
      const fontSize = Number.parseFloat(value.fontSize);
      const family = String(value.fontFamily)
        .split(",")[0]
        .trim()
        .replace(/^["']|["']$/g, "");
      return {
        fontFamily: family,
        fontSize,
        lineHeight: Math.round(fontSize * Number(value.lineHeight)),
        fontWeight: String(value.fontWeight),
      };
    }
  }
  if (typeof value === "string") {
    const ms = /^(\d+)ms$/.exec(value);
    if (ms) return Number(ms[1]);
    const spring = /^damping (\d+) stiffness (\d+) mass (\d+)$/.exec(value);
    if (spring) {
      return { damping: Number(spring[1]), stiffness: Number(spring[2]), mass: Number(spring[3]) };
    }
  }
  return value;
}

function group(module, groups) {
  const out = {};
  for (const [name, raw] of Object.entries(module)) {
    const match = groups.find(([prefix]) => name.startsWith(prefix));
    if (!match) continue;
    const [prefix, key] = match;
    out[key] ??= {};
    out[key][lowerFirst(name.slice(prefix.length))] = normalize(raw);
  }
  return out;
}

const base = group(await import("@xos/tokens/native/base"), BASE_GROUPS);
const themes = {};
for (const theme of THEMES) {
  themes[theme] = group(await import(`@xos/tokens/native/theme.${theme}`), THEME_GROUPS);
}

const source = `/* Generated by scripts/generate-theme.mjs from the @xos/tokens React Native build. Do not edit; run \`pnpm --filter @xos/ui-native generate:theme\`. */

/** Theme-independent tokens in React Native units: points, milliseconds and unitless ratios. */
export const baseTokens = ${JSON.stringify(base)} as const;

/** Colors and shadows per theme. Dark is the default; Sunlight is the Compass outdoor theme (decision D3). */
export const themeTokens = ${JSON.stringify(themes)} as const;
`;

const config = (await prettier.resolveConfig(target)) ?? {};
const output = await prettier.format(source, { ...config, filepath: target });

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch (error) {
    console.error(`Cannot read ${target}: ${String(error)}`);
    process.exit(1);
  }
  if (current !== output) {
    console.error(
      "src/theme/tokens.generated.ts is out of date. Run pnpm --filter @xos/ui-native generate:theme.",
    );
    process.exit(1);
  }
} else {
  writeFileSync(target, output);
}
